std::vector<std::byte> CanonicalHalfBytes(std::span<const std::uint16_t> components){std::vector<std::byte> result;result.reserve(components.size()*2);for(const auto value:components){result.push_back(std::byte(value&0xffu));result.push_back(std::byte(value>>8));}return result;}

