class CanonicalReader {
public:
    explicit CanonicalReader(std::span<const std::byte> bytes):bytes_(bytes){}
    template<class T> requires std::is_integral_v<T> bool Integer(T& value){using U=std::make_unsigned_t<T>;if(sizeof(U)>bytes_.size()-offset_)return false;U bits{};for(std::size_t index=0;index<sizeof(U);++index)bits|=U(std::to_integer<std::uint8_t>(bytes_[offset_++]))<<(index*8);value=static_cast<T>(bits);return true;}
    template<class T> requires std::is_enum_v<T> bool Integer(T& value){std::underlying_type_t<T> bits{};if(!Integer(bits))return false;value=static_cast<T>(bits);return true;}
    bool Boolean(bool& value){std::uint8_t bits{};if(!Integer(bits)||bits>1)return false;value=bits!=0;return true;}
    bool Float(float& value){std::uint32_t bits{};if(!Integer(bits))return false;value=std::bit_cast<float>(bits);return !(value==0.f&&bits!=0);}
    bool Double(double& value){std::uint64_t bits{};if(!Integer(bits))return false;value=std::bit_cast<double>(bits);return !(value==0.0&&bits!=0);}
    bool Hash(GameplayProductionHash2563D& hash){for(auto& value:hash)if(!Integer(value))return false;return true;}
    [[nodiscard]] std::size_t Remaining()const noexcept{return bytes_.size()-offset_;}
    [[nodiscard]] bool End()const noexcept{return offset_==bytes_.size();}
private:std::span<const std::byte> bytes_;std::size_t offset_{};
};

